const http = require('node:http');
const https = require('node:https');
const fetch = globalThis.fetch || ((urlString, options = {}) => new Promise((resolve, reject) => {
  const transport = String(urlString).startsWith('https://') ? https : http;
  const req = transport.request(urlString, {
    method: options.method || 'GET',
    headers: options.headers || {},
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk.toString();
    });
    res.on('end', () => {
      resolve({
        ok: (res.statusCode || 0) >= 200 && (res.statusCode || 0) < 300,
        status: res.statusCode || 0,
        text: async () => body,
        json: async () => body ? JSON.parse(body) : {},
      });
    });
  });
  req.on('error', reject);
  if (options.body) {
    req.write(options.body);
  }
  req.end();
}));

const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
if (!runnerBase) {
  throw new Error('AUTOMATION_RUNNER_BASE_URL env var is required');
}
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};
const payload = $json.body ?? $json;
const branch = String(payload.ref || '').replace('refs/heads/', '');
const commits = Array.isArray(payload.commits) ? payload.commits : [];
const compareUrl = payload.compare || '';
const lines = commits.slice(-10).map((commit) => `- ${commit.message} (${String(commit.id || '').slice(0, 7)})`);
const summary = [
  `Branch: ${branch || 'unknown'}`,
  compareUrl ? `Compare: ${compareUrl}` : '',
  '',
  'Recent commits:',
  ...(lines.length > 0 ? lines : ['- No commits supplied in webhook payload.']),
].filter(Boolean).join('\n');

const reportRelativePath = `github-commit-summaries/${new Date().toISOString().replace(/[:]/g, '-')}-${(branch || 'unknown').replace(/[^a-zA-Z0-9._-]+/g, '-')}.md`;
const writeReport = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: ['# Commit Summarizer', '', summary].join('\n') }),
});
if (!writeReport.ok) throw new Error(`reports/write failed: ${writeReport.status}`);

let planeUpdate = null;
const taskMatch = branch.match(/task[-_](\d+)/i);
if (taskMatch && $env.PLANE_API_KEY) {
  const planeBase = $env.PLANE_API_BASE_URL;
  const planeWorkspace = $env.PLANE_WORKSPACE_SLUG;
  const planeProject = $env.PLANE_PROJECT_ID;
  if (!planeBase || !planeWorkspace || !planeProject) {
    throw new Error('PLANE_API_KEY is set but PLANE_API_BASE_URL, PLANE_WORKSPACE_SLUG, or PLANE_PROJECT_ID is missing');
  }
  const externalId = `TASK-${taskMatch[1].padStart(3, '0')}`;
  const itemsResponse = await fetch(`${planeBase}/api/v1/workspaces/${planeWorkspace}/projects/${planeProject}/work-items?per_page=200&fields=id,name,description_html`, {
    headers: { 'X-API-Key': $env.PLANE_API_KEY },
  });
  if (itemsResponse.ok) {
    const itemsJson = await itemsResponse.json();
    const items = Array.isArray(itemsJson.results) ? itemsJson.results : [];
    const marker = `External ID:</strong> <code>${externalId}</code>`;
    const item = items.find((entry) => String(entry.description_html || '').includes(marker));
    if (item) {
      const escapedSummary = summary.replace(/[<&>]/g, (char) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;' }[char]));
      const summaryBlock = `<h3>Latest Commit Summary</h3><pre>${escapedSummary}</pre>`;
      const existingDescription = item.description_html || '';
      const summaryRegex = /<h3>Latest Commit Summary<\/h3><pre>[\s\S]*?<\/pre>/;
      const newDescription = summaryRegex.test(existingDescription)
        ? existingDescription.replace(summaryRegex, summaryBlock)
        : `${existingDescription}${summaryBlock}`;
      const patchResponse = await fetch(`${planeBase}/api/v1/workspaces/${planeWorkspace}/projects/${planeProject}/work-items/${item.id}/`, {
        method: 'PATCH',
        headers: {
          'X-API-Key': $env.PLANE_API_KEY,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ description_html: newDescription }),
      });
      planeUpdate = {
        externalId,
        workItemId: item.id,
        ok: patchResponse.ok,
        status: patchResponse.status,
      };
    }
  }
}

const contextResponse = await fetch(`${runnerBase}/context/last-commit-summary`, {
  method: 'PUT',
  headers,
  body: JSON.stringify({ value: { branch, summary, planeUpdate, reportRelativePath } }),
});
if (!contextResponse.ok) {
  const body = await contextResponse.text();
  throw new Error(`context/last-commit-summary failed: ${contextResponse.status} ${body}`);
}

return [{ json: { branch, summary, planeUpdate, reportRelativePath } }];
